<?php
declare(strict_types=1);

/**
 * Update log shown at /updates. Newest first. Times are local time (Europe/Stockholm).
 * Add a new entry at the TOP with every update: [version, 'YYYY-MM-DD HH:MM', 'Headline', ['point', ...], 'fix|new|improve']
 */
return [
    ['3.64.0', '2026-11-27 22:10', 'New tour video', ['New A new video tour of the site: feed, logging, quests, muscle levels, achievements, bosses, wardrobe, shop, teams, leaderboards and insights.'], 'new'],
    ['3.63.0', '2026-11-27 21:50', 'Wardrobe stays put, male and female looks', ['Fix Try on, buy and wear in the wardrobe now update in place. The page no longer jumps, and you keep your tab and scroll position.', 'New Choose a male or a female look for your animal on the character page (free to change): heavier brows and cheek fur, or lashes, a hair tuft and a bow.', 'Fix The Wings tab no longer breaks into two lines on phones.'], 'new'],
    ['3.62.0', '2026-11-27 21:10', 'More life on the front page', ['New The dress-up demo changes outfit, wings and aura by itself with a soft fade and a sparkle ring, and your hero floats. Pick anything yourself and it stops.', 'New Muscle bars fill up, one muscle levels up with a LEVEL UP flash, then the week fills in and the damage bonus counts up to +12%.'], 'new'],
    ['3.61.0', '2026-11-27 20:30', 'Design your hero', ['New Wardrobe: press Buy and wear all to buy and put on everything you are trying, in one click.', 'New Your character preview stays on screen while you scroll the wardrobe (on by default on computers, one button to switch on or off on phones).', 'Improve Buying or wearing in the wardrobe keeps your try-on and takes you back to the item list, so no more scrolling.', 'New Front page: dress the hero in outfits, wings and auras and see the muscle levels.'], 'new'],
    ['3.60.0', '2026-11-27 19:40', 'Team chat and moving wings', ['New Team chat on every team page. Only members can read and write, you can delete your own messages and leaders can delete any.', 'New Wings flap and auras pulse, flicker, sparkle or spin on your character page, profile and wardrobe. Lists stay still so the site stays fast.'], 'new'],
    ['3.59.0', '2026-11-27 19:00', 'New gear art', ['New All 7 gear sets are redrawn with their own shapes: capes, tabards, horned and winged helms, spiked pauldrons, glowing swords and more.', 'New 16 new look-only outfit sets: Samurai, Viking, Shadow, Archmage, Pirate, Royal, Ranger, Frostguard, Dragonscale, Gladiator, Sakura, Reaper, Tidecaller, Tribal, Obsidian Knight, Golden Guard and Crusader.', 'New Look-only wings, auras and necklaces in many colours in the Wardrobe.', 'Improve Item icons now show the same drawing your character wears.'], 'new'],
    ['3.58.0', '2026-11-27 18:00', 'Wardrobe and fitting room', ['New Wardrobe: try on any gear, even things you cannot buy yet, and see how your character looks.', 'New Look-only outfits for every set. They cover your stat gear, give no bonus and need no level.', 'New Mid and top gear sets now need a muscle level too: Legs for boots, Arms for weapons and gloves, Shoulders for helmets, Chest or Back for armor.'], 'new'],
    ['3.57.0', '2026-11-27 17:10', 'Muscle levels', ['New Every muscle now levels up from the sets you log, shown on the new Muscle levels page.', 'New Train many body areas in a week to get up to +12% boss damage.', 'New 10 new achievements for muscle levels, training every muscle and full body weeks.'], 'new'],
    ['3.56.2', '2026-11-27 16:30', 'Better prize when the boss escapes', ['Improve A boss that escapes now pays 40% of the prize pool, up from 25%, and its unique loot can still drop at 40% of the normal odds.'], 'improve'],
    ['3.56.1', '2026-11-27 16:20', 'Bigger weekly boss prize', ['Improve The weekly boss prize pool now starts at 200 coins and grows by 30 for every hero who hits it, up to 500.'], 'improve'],
    ['3.56.0', '2026-11-27 15:20', 'Alert mail on the Mentions page', ['Improve Google Alerts and F5Bot mails sent to the site mailbox are read automatically and listed on the Mentions page. The web search was removed.'], 'improve'],
    ['3.55.0', '2026-11-27 14:40', 'Mentions search runs on the site', ['Improve The search for Fitocracy-related posts now runs on the website itself, with a Run search now button, and once a day through the cron job. No extra computer needed.'], 'improve'],
    ['3.54.0', '2026-11-27 14:00', 'Traffic by visitor', ['Improve Traffic now counts one visitor per browser and day, with where they came from, which pages they opened and a human score. Filters refresh the list without jumping to the top, and the list reads well on a phone.', 'Improve Your own browser is left out of the statistics once you open admin.', 'New Mentions: edit the search words, press Run search now and see when the nightly search last ran.'], 'improve'],
    ['3.53.0', '2026-11-27 13:10', 'Mentions page in admin', ['New Admin has a Mentions page that lists posts on the web where people talk about Fitocracy or ask for an alternative, with a match percentage. Mark them replied or ignored.'], 'new'],
    ['3.52.0', '2026-11-27 12:50', 'Traffic: who is real?', ['New A Traffic page in admin shows every visit with a score for how likely it is a real person, JavaScript on or off, country and source, with filters for likely human, uncertain and likely bot.', 'Improve The admin menu is now grouped under People, Content, Insights and Site.'], 'new'],
    ['3.51.2', '2026-11-27 11:15', 'Exact exercises from SnakeDiet', ['Improve Workouts from SnakeDiet can name the exact exercise with its slug, so no name guessing is needed.'], 'improve'],
    ['3.51.1', '2026-11-27 11:00', 'More exercise names from SnakeDiet', ['Improve 20 more SnakeDiet exercise names are linked to the right exercise here (for example Reverse Flyes, Crunches, Ab Roller and Farmer\'s Walk).'], 'improve'],
    ['3.51.0', '2026-11-27 10:40', 'Smarter exercise matching from SnakeDiet', ['Improve Workouts from SnakeDiet now come in with their real sets. Exercise names like "Barbell Bench Press - Medium Grip" or "Dumbbell Bicep Curl" are matched to the right exercise here. Names that cannot be matched are shown in the Connect log and added to the workout note.'], 'improve'],
    ['3.50.1', '2026-11-27 10:20', 'SnakeDiet: skip very old workouts', ['Fix Editing a workout older than about two months no longer tries to send it to SnakeDiet, which only accepts the last 60 days. It is skipped quietly, not shown as an error.'], 'fix'],
    ['3.50.0', '2026-11-27 10:10', 'Site log', ['New Admin > Logs keeps errors, warnings and security events for 30 days: failed logins, rate limits, refused API keys and non-admins on admin pages. Each filter shows the last 24 hours and a box with the latest lines to copy.', 'Improve PHP errors are now written to a log outside the public folder. The log never holds passwords, keys or search words, and it is explained in the privacy page.'], 'improve'],
    ['3.49.0', '2026-11-27 09:50', 'SnakeDiet stays in sync', ['New Edited and deleted workouts are now updated or removed on SnakeDiet too, and the same works the other way round. Nothing is counted twice.', 'New The Connect page has a copyable log of the last 20 calls in and out. A plain log file is also kept on the server outside the public folder.', 'New A public /api/v1/ping shows which version is live. The API guide now lists every field and error code.'], 'new'],
    ['3.48.0', '2026-11-27 09:40', 'Workouts from SnakeDiet', ['New Workouts you log on SnakeDiet now arrive here as real workouts: they show in your history and feed and earn points like your own. Minutes and calories are kept, and lines like "Bench press — 3×8 @ 80 kg" become real sets when the exercise is known.', 'Improve Workouts that came from SnakeDiet are never sent back to it. The Connect page log shows what came in.'], 'new'],
    ['3.47.6', '2026-11-27 09:00', 'Call log for SnakeDiet and webhooks', ['New The Connect page lists the last 20 outgoing calls (time, address, status and the first part of the reply). Your key is never shown.', 'Improve A failed resend now shows the full reply and the exact address that was called. Only successful resends count toward the limit of 3 per 10 minutes.'], 'new'],
    ['3.47.5', '2026-11-27 08:45', 'Clearer resend errors', ['Fix The SnakeDiet resend button now shows why a workout was refused.'], 'fix'],
    ['3.47.4', '2026-11-27 09:10', 'Sets to SnakeDiet and resend', ['Improve Workouts sent to SnakeDiet now include every set (exercise, reps or seconds, and weight in kg), so SnakeDiet can count calories from the real load.', 'New Connect page: a "Resend last 7 days to SnakeDiet" button for when you set up the link after training. Workouts SnakeDiet already has are skipped.'], 'new'],
    ['3.47.3', '2026-11-27 08:40', 'Workouts go to SnakeDiet as workouts', ['Improve If your webhook points at SnakeDiet, each finished workout is now sent as a real workout (time, type and one line per exercise), so SnakeDiet counts calories and KTN itself. It is no longer posted as a feed message there.'], 'improve'],
    ['3.47.2', '2026-11-27 07:00', 'Workout details in SnakeDiet posts', ['New When a finished workout is posted to SnakeDiet (or another site), it now includes one line per exercise, like "Bench press — 4×8 @ 80 kg", in your own unit.'], 'new'],
    ['3.47.1', '2026-11-27 05:50', 'Shop preview fix', ['Fix Name effect previews in the Shop were too big on phones and overlapped their labels. They now fit on one line.'], 'fix'],
    ['3.47.0', '2026-11-27 02:30', 'Gear sets and a clearer Shop', ['New Seven matching gear sets (Wanderer, Scout, Ironclad, Merchant, Champion, Mythril and Stormforged), each with a weapon, helmet, armor, gloves and boots that look alike on Fito. Wearing 3 pieces gives a bonus and all 5 a bigger one. Themes: damage, coins or balanced.', 'New An Equipment overview at the top of the Shop shows all 8 slots, your total bonus and active set bonuses. Every item shows what it would replace and how it compares before you buy or swap.', 'Improve Gear icons are now drawn in the same colours Fito wears them in, so the shop matches your character.', 'Fix The Shop and Character pages no longer jump back to the top when you buy, equip or change something.', 'Improve Older loose items you do not own are no longer sold; the ones you own stay under Other gear.'], 'new'],
    ['3.46.0', '2026-11-27 01:40', 'Your character', ['New Your character page: Fito wears the gear you equip. Early gear looks rough (a stick, rags), then leather, steel, gold, and finally glowing mythic armor. Weapons, armor, helmets, gloves, boots, charms, wings and auras all show.', 'New Pick your animal (wolf, bear, fox or panther) and your eye colour. The first animal pick is free, later changes cost 250 coins. Eye colour is always free.', 'New A mood meter that follows how recently you trained.', 'New Your character also shows on your profile, so others can see your gear.'], 'new'],
    ['3.45.1', '2026-11-27 00:50', 'Sell gear, level requirements', ['New You can sell gear you bought back to the Shop: 80% of the price when new, falling to 30% after about two months. Boss drops and achievement items cannot be sold.', 'New The best gear needs a level (from level 5 up to level 30 for the top items). Cheap gear is open to everyone.', 'Improve The Shop now says that you wear one item per slot, so items do not stack.'], 'new'],
    ['3.45.0', '2026-11-27 00:10', 'Long-term progression', ['Improve A new level curve built for steady training: level 20 in about 6 weeks, level 50 in about 6 months, level 100 in about 2.5 years at 3.5 workouts a week and 6,000 steps a day.', 'Improve Steps are worth a bit more (80 steps per point instead of 120).', 'New 30 easier and consistency achievements: low bodyweight rungs for each lift, days visited, days trained, busy weeks in a row and days with a post (one post per day counts).', 'New Achievements now unlock items that cannot be bought: gear, plus avatar frames, banners and name effects. See your Milestones page.', 'New 30 day potions in the Shop and 9 more pieces of gear.'], 'new'],
    ['3.44.0', '2026-11-26 22:30', 'Faster levels, more achievements, Boosts page', ['Improve Levels now come about twice as fast (level 50 needs about 105,000 points instead of 210,000). Everyone is recalculated automatically.', 'Improve Warm-up sets now earn full points. They still never count as personal records.', 'New 20 new achievements: strength relative to bodyweight (bench, squat, deadlift, overhead press, row), time spent training, 100 workouts and a 30 day streak.', 'New Boosts page in the menu: shows every bonus on your workouts and how long each lasts.', 'New Insights shows total time training and your average workout length.', 'Fix The Title, gym and time panel in the logger now has a Done button and closes with Enter.'], 'new'],
    ['3.43.0', '2026-11-26 18:30', 'Typo guard and admin tools', ['New Weights that no person could lift (a 1,000 kg deadlift, 100 kg curls) are refused with a friendly message, so a typo cannot wreck a boss fight. Unusually heavy sets still save but are flagged privately for the team.', 'Improve Dumbbell exercises now remind you to log one dumbbell and count reps once.', 'New Admin Tools tab: give or take coins and XP, gift any item with a message, see flagged sets and a log of every change.'], 'new'],
    ['3.42.1', '2026-11-26 17:50', 'Fairer points for timed holds', ['Fix Planks, wall sits, L-sits and other timed holds paid far too little compared with lifting and cardio (a 2 minute plank gave 6 points). They now pay three times as much, in line with other exercises per minute of effort. Workouts you already saved keep their points.'], 'fix'],
    ['3.42.0', '2026-11-26 17:20', 'Style your profile', ['New Three new kinds of shop items, bought with coins: name effects (Ember, Frost, Gold, Neon, Aurora, Glitch), avatar frames and profile banners. They are cosmetic only, so they do not change damage or coins.', 'New Your name effect shows everywhere your name does, your frame around your photo, and your banner on your profile. Equip them in the Shop.'], 'new'],
    ['3.41.1', '2026-11-26 16:35', 'A friendlier first workout', ['New New members see a short guide from Fito above the logger: start, add an exercise, tick the sets, finish. It disappears after the first saved workout.'], 'new'],
    ['3.41.0', '2026-11-26 16:10', 'Fito coaches you', ['New A short note from Fito at the top of the feed, based on your own training: nudges after a few days off, a shout-out for a new record, or a hint when you push much more than you pull or skip legs. It is rule based, so it costs nothing and is private to you.'], 'new'],
    ['3.40.1', '2026-11-26 15:50', 'App: no more self-installing', ['Improve Android app 1.13 no longer asks for the permission to install other apps. The update button now opens the download in your browser instead, which should make Google Play Protect less suspicious.', 'Improve The Android page explains the Play Protect warning and what to tap.'], 'improve'],
    ['3.40.0', '2026-11-26 15:20', 'Share your workout as a picture', ['New A Make picture button on your own workouts creates a shareable image with Fito, your points, the exercises and any PRs. It is made in your browser, so nothing is uploaded; on a phone it opens the share sheet.', 'Improve Android widgets (app 1.12): new Wolf theme and Ice accent as the default look for new widgets, and Fito on the level widget. Widgets you already placed keep their style.'], 'new'],
    ['3.39.0', '2026-11-26 14:40', 'Insights: your training in numbers', ['New A private Insights page (menu > Insights): workouts, volume, sets, reps, training days and streaks.', 'New Weekly volume chart, push / pull / legs balance with sets per muscle for the last 30 days, and which weekdays you train.', 'New Your records (best estimated one-rep max per lift) and an exercise explorer with graphs for one-rep max, heaviest set and volume per session, plus your latest sessions.'], 'new'],
    ['3.38.2', '2026-11-26 14:10', 'Demo matches the exercise', ['Fix The landing page demo now says Push day for bench press, Leg day for squats and Pull day for curls.'], 'fix'],
    ['3.38.1', '2026-11-26 13:55', 'Fito trains, and the site runs smoother', ['New Fito does a bench press, back squat and dumbbell curl (you see the biceps swell), and the landing page demo cycles through them above the card instead of covering it.', 'New The save screen after a workout is longer and shows Fito doing the exercises you just logged.', 'Improve The logo in the top bar is now just his head so it fits the menu.', 'Improve Smoother scrolling: removed the heavy blur on the background glow, lighter glass on the menu bars, and the floating background pauses while you scroll. Fade-and-focus on scroll now also works on the public pages.'], 'improve'],
    ['3.38.0', '2026-11-26 13:20', 'Meet Fito', ['New Fito the wolf is the new mascot. He breathes, blinks, wags his tail, flexes, cheers and lifts, and on the landing page his head follows your cursor.', 'New Finishing a workout now plays a short lifting animation with your points counting up while the workout is saved.', 'New New app icon, favicon and share image. The Android app (1.11) gets the new icon after the next update.', 'Improve The mascot stays still on the Track page and for people who prefer reduced motion.'], 'new'],
    ['3.37.0', '2026-11-26 12:40', 'More motion, calm where you train', ['New Pages now ease in as you scroll: cards slide up and sharpen, with a thin progress bar at the top and a glassy header.', 'New Buttons get a light sweep and a tap ripple, tiles tilt in 3D under the mouse, badges bounce, and pages crossfade when you move between them (Chrome and the Android app).', 'Improve The Track page and the routine editor stay still: no floating background, no glow, no extra effects, so nothing distracts or drains the battery mid-set.', 'Improve Everything switches off for people who prefer reduced motion, and the heavy parts are skipped on weak phones or data saver.'], 'new'],
    ['3.36.2', '2026-11-25 17:30', 'Story post: your data and tools', ['Improve The launch story now explains the personal API key, CSV and JSON export, Google Sheets, calendar feed and the widgets for Android, Windows, macOS and iPhone.'], 'improve'],
    ['3.36.1', '2026-11-25 17:10', 'Researched Fitocracy history post', ['Improve The post on what happened to Fitocracy now covers the documented timeline, what is not known, and a first-hand account, with sources.'], 'improve'],
    ['3.36.0', '2026-11-25 16:05', 'A blog', ['New A blog at /blog with an editor for admins (Admin > Blog): drafts, scheduling, SEO checklist, RSS feed, sitemap entries and article markup for Google.', 'New Three launch posts are waiting as drafts: why MyFitLevel exists, what happened to Fitocracy, and a guide to Fitocracy alternatives.', 'New Latest posts show on the landing page and a Blog link was added to the footer.'], 'new'],
    ['3.35.3', '2026-11-25 13:50', 'Step sync status in the menu', ['New The menu now shows your steps today and when they were last updated, right under your level. It turns amber if nothing has synced for a few hours. Tap it for details.'], 'new'],
    ['3.35.2', '2026-11-25 13:35', 'Steps connect card shows up in the app', ['Fix The Connect / Reconnect this phone card on the Steps page is now shown whenever the page is opened in the Android app (recognised by user agent, app cookie or Android WebView), so it no longer depends on one header.'], 'fix'],
    ['3.35.1', '2026-11-25 12:30', 'Easier steps connection in the Android app', ['Fix The Steps page inside the app now always shows a Connect / Reconnect this phone button (it was hidden when the site still remembered an old connection).', 'New After you log in, the app asks once if you want to sync steps with Health Connect, and once more if the phone is linked but steps are not allowed yet. Say Not now and it will not ask again. Steps stay optional.'], 'improve'],
    ['3.35.0', '2026-11-25 11:44', 'Android widgets, points wording and tidier updates', ['New Android app 1.2 has 11 home-screen widgets: Everything (big dashboard), Level, Steps, Boss, Week and streak, Daily chest, Quick buttons, Log workout, Feed, Feed ticker and Minimal stats. Each can get its own colours, corners and see-through level, and shows when it was last updated with a refresh button.', 'New A Widgets gallery inside the app with a picture of every widget and an Add button. Press and hold the app icon for quick actions: Log workout, Steps, Boss and Feed.', 'New API: GET /api/v1/widgets returns everything the widgets need in one call.', 'Improve This page now groups updates made within a few hours into one block, with the versions listed under it.', 'Fix It is points everywhere, not XP: the link preview image, messages and team texts. Distance is gone from the landing steps card.'], 'new'],
    ['3.34.1', '2026-11-25 11:30', 'Prettier landing stats', ['New Landing stats are now cards. One big card swaps between kg and lb every few seconds (tap to choose).', 'Fix Sets and reps now count only gym exercises (weights and bodyweight), not walks, runs or other activities.', 'New Steps walked, and a Popular beyond the gym row that shows the most-logged runs, ski sessions and other non-gym activities once they get popular.'], 'improve'],
    ['3.34.0', '2026-11-25 11:20', 'Live landing stats and a much better admin Stats page', ['New Landing page numbers now count up and show both kg and lb, plus sets, reps, lifters and average workouts per lifter. Big numbers shorten to K, M and B (5,085, 12.3K, 123K, 1.2M).', 'New Admin Stats is rebuilt: Overview chart, Sources, Pages, Audience and Privacy tabs.', 'New See where visitors come from (Google, Facebook, other sites, campaign links), which page they landed on, and how many became members. Stored as anonymous numbers only, never tied to a person.', 'New New vs returning visitors (for people who pressed OK on cookies), countries with flags, bots and devices.'], 'new'],
    ['3.33.1', '2026-11-25 10:45', 'Android app: one icon, no offer inside the app', ['Fix The Android offer no longer shows inside the app itself (or any Android WebView).', 'Improve The Android app now has a single icon and syncs your steps as soon as you open it, as well as about once an hour in the background.'], 'fix'],
    ['3.33.0', '2026-11-25 08:30', 'Android app page and open-source badges', ['New Landing page now shows Open source, Android app and Open API right under the buttons.', 'New An Android app page with a direct download from GitHub and simple install steps. Android visitors get a one-time offer of the app (not inside the app itself, and never again after Not now).'], 'new'],
    ['3.32.0', '2026-11-25 08:10', 'Open source', ['New MyFitLevel is now open source (AGPL-3.0). The website and the Android app live on GitHub, with install instructions and a way to contribute. There is an Open source link in the footer and on the About page.'], 'new'],
    ['3.31.1', '2026-11-25 06:36', 'Update times fixed', ['Fix The times shown on this Updates page were a couple of hours ahead. They are correct now.'], 'fix'],
    ['3.31.0', '2026-11-25 06:32', 'New level curve', ['Improve Levels are retuned now that steps, seasons and daily rewards add points. The start is a bit slower (your first workout is level 2, a first week lands around level 4-5), and the climb gets steadily harder.', 'Improve Active members (3-4 sessions a week, daily steps, quests and boosts) reach level 50 in about a year and level 100 in about three. Relaxed members get there later. Levels are recalculated automatically for everyone.'], 'improve'],
    ['3.30.0', '2026-11-25 06:25', 'Messages, profile activity and seasons all year', ['New Private messages: tap Message on any profile, open your inbox from the chat icon at the top, block anyone you do not want to hear from.', 'New Profiles now show what earned the points: steps (with points), boss hits grouped per day, and rare loot like relics and advent treasures. Coins are not shown.', 'New Season calendar that creates itself all year: New Year, spring, Easter, Back to the Gym, Halloween, Gains Friday, Christmas, and a Boss Weekend every month.', 'New Summer Holiday Boost: +10% points and coins from 15 June to 1 September, when most of the world is on holiday.', 'Improve Admin events are now clear tiles instead of one long row of buttons, and the public Events page shows the year ahead.'], 'new'],
    ['3.29.0', '2026-11-25 06:15', 'Daily chest on the start page, advent calendar and boss relics', ['New Your daily chest now sits at the very top of the feed with a big Open button (and slims down once opened).', 'New Advent calendar 1-24 December: everyone gets the same gift each day, but a door can only be opened on its own day. Doors 1-19 give potions and coins, doors 20-24 give permanent treasures (Yule Star, Frostlight Aura, Reindeer Antlers, Candy Cane Blade and the rare Angel Wings).', 'New Legendary boss relics: every boss kill has a 1% chance to drop a permanent relic (+10% to +20% damage or coins, stronger from tougher bosses) for one lucky hero, picked by damage share.', 'New Wings, Auras and Boss relics gear slots.'], 'new'],
    ['3.28.0', '2026-11-25 03:30', 'Boss hit feed, light theme and skins', ['New Recent hits feed on the weekly boss page and on team raids: who hit, with a workout or steps, how hard and how long ago.', 'Several hits by the same person in a row fold into one line with an arrow you can open, so updating steps a few times a day does not flood the list.', 'Fixed the white-on-white header and menu button in the light theme.', 'Effects, buttons and the glow now follow your chosen skin colours instead of always being purple.'], 'improve'],
    ['3.27.1', '2026-11-25 02:50', 'Calmer, classier background', ['The cartoon-like dumbbells are gone. The background now has glowing sparks rising like points, plus huge soft out-of-focus barbell and plate shapes far behind.', 'The cursor light is softer and violet instead of green.', 'Front page pill text changed.'], 'improve'],
    ['3.27.0', '2026-11-25 02:30', 'Redesign: near-black, indigo and neon', ['New look inspired by niemi.nu: deep black background with purple, teal and pink glows, indigo buttons, cyan-to-pink headlines and big bold type.', 'New day/night switch with a starry moon and a sunny sky.', 'Front page redesigned with a status pill, huge animated headline and a glowing demo card.', 'Green accents are now indigo and cyan across the site.'], 'new'],
    ['3.26.0', '2026-11-25 02:00', 'Gym-themed living background', ['Floating dumbbells, plates, kettlebells, coins, stars and +XP numbers drift across the background and move away from your mouse.', 'A soft light follows your cursor, and cards light up where you hover.', 'New day/night switch in the top bar, glowing buttons, an animated headline on the front page and a spark burst when you press buttons.', 'Everything calms down automatically if your device is set to reduce motion.'], 'new'],
    ['3.25.2', '2026-11-25 01:40', 'Tracker fix and iPhone video guide', ['Fixed the exercise picker on the Track page (the new glass effect pushed it out of place on computers).', 'New one-minute video guide for the iPhone Shortcut on the Steps page.'], 'fix'],
    ['3.25.1', '2026-11-25 01:20', 'Steps page fix', ['The steps and week totals at the top of the Steps page are laid out properly again.', 'Sites that had saved the old step rate (1 point per 300 steps, 12,000 a day) now move to the new one (120 and 20,000).'], 'fix'],
    ['3.25.0', '2026-11-25 01:00', 'New look: menu icons, key popup, motion', ['Every menu item now has its own icon and colour, and the menu scrolls on small phones so nothing is cut off.', 'Creating an API key opens a popup: tap the key to copy it. The key list is cleaner too.', 'Whole site restyled: slow aurora glow background, glass cards, floating bottom bar, glowing buttons and fields, and a tidy admin menu and tables.', 'Smoother feel: pages fade in, cards lift, buttons and the XP bar glow and animate (switched off automatically if your phone is set to reduce motion).'], 'improve'],
    ['3.24.1', '2026-11-25 00:30', 'Easier iPhone guide, keys you can always copy', ['The iPhone Shortcut guide is now step by step with screenshots and a Copy button for every value, with your own key already filled in.', 'API keys can now be viewed and copied any time in Settings, and creating one jumps straight back to the key list.'], 'improve'],
    ['3.24.0', '2026-11-25 01:00', 'Steps hit the boss, more coins and quests', ['Steps are worth more: 1 point per 120 steps up to 20,000 a day, so a 10k walk is about 83 points. Admin can tune it.', 'Your steps now damage the weekly boss and your team boss too, using your level and gear.', 'Coins for walking: 6 at 5,000 steps, 12 more at 10,000 and 18 more at 15,000, once a day.', 'Welcome bonus: workouts from before the game now give a one-time coin bonus.', 'About 12 new quests and 5 new badges: walking days, total steps, joining or founding a team, boss kills and more.', 'Points & coins page redesigned with big tabs, bars and a clear "how to earn coins" card.', 'New step-by-step iPhone Shortcut guide on the Steps page.'], 'new'],
    ['3.23.0', '2026-11-25 00:10', 'Holiday events and steps', ['New Points & coins page: see exactly where every point and coin came from, with a full coin history.', 'Steps bar on the home page (optional, with your own daily goal).', 'You can now have many API keys, each named, and creating one never replaces another. The Android app links itself with one tap, no key to copy.', 'Android app: steps sync from Health Connect (download link on the Steps page). Guest feedback with links or SEO pitches is dropped as spam.', 'Steps now earn a few points (1 per 300 steps, capped per day, configurable in admin). Fill in any of the last 14 days; phone sync only raises a day.', 'Events can now boost coins and boss damage as well as points, with one-click Christmas, New Year and Boss Weekend presets in admin.', 'New Steps page: log steps and distance by hand, or send them automatically from an iPhone Shortcut or any app through the API.', 'Teams get a weekly steps quest.'], 'new'],
    ['3.21.0', '2026-11-24 21:00', 'Game news, seasons and badges', ['Game news in the feed and on the boss page: boss kills, rare drops, team level-ups, raid wins and season results.', 'Monthly boss seasons: top 3 players get a title and a rare item, the best team wins 1,200 coins for its vault.', 'Team emblem and season trophy now show next to names across the site.'], 'new'],
    ['3.20.6', '2026-11-24 19:40', 'Daily chest', ['Open a free chest every day. The streak runs 7 days and day 7 pays 120 coins. Missing a day resets it.'], 'new'],
    ['3.20.5', '2026-11-24 19:10', 'Bigger shop, longer potions, fuller vaults', ['Potions now come in 3 and 7 day versions that are much cheaper per day, plus coin potions.', '20 new items and three new gear slots: helmets, gloves and boots.', 'Team buffs last 7 days, and the team vault now fills itself from raid loot and finished quests.'], 'new'],
    ['3.20.3', '2026-11-24 18:30', 'Choose your raid boss, team ranking and stats', ['Weekly team contest: the 3 teams with the most points per member win 300 / 150 / 75 coins for their vault, and every team page shows its own weekly member leaderboard.', 'Teams pick their own raid boss. Tougher bosses unlock with team level and pay more.', 'New team ranking with weight lifted, workouts, distance, points and boss kills, plus a stats card on every team page.', 'Leaders decide whether officers may spend the vault.'], 'new'],
    ['3.20.2', '2026-11-24 17:10', 'Team vault, buffs and perks', ['Teams now have a vault: members give coins, leaders and officers spend them on buffs that help everyone.', 'Buffs: Battle Cry and Warband (boss damage), Fortune (coins), Rally (team XP).', 'Team level gives permanent perks: +1% boss damage per level and more coins at higher levels.'], 'new'],
    ['3.20.1', '2026-11-24 16:40', 'Team founding costs coins, plus team and boss badges', ['Starting a team now costs coins (100 by default, change it in Admin > Game). Joining stays free.', 'A team that never gets a second member closes after 14 days, so the list stays tidy.', 'New badges: Squad Up, Team Founder, Boss Slayer and Boss Hunter.'], 'improve'],
    ['3.20.0', '2026-11-24 16:10', 'Weekly boss, coins, shop and teams', ['A public weekly boss: every workout you log damages it automatically, and higher levels hit harder.', 'When it falls, the coin prize is split by damage share and every hero rolls for its unique item.', 'Coins from workouts, a shop with gear and potions, and an animated boss page on the home screen and front page.', 'Teams: open or closed, invite or ask to join, team levels with more slots, weekly team quests and a team raid boss, with notifications.'], 'new'],
    ['3.19.6', '2026-11-23 12:05', 'One-line Pi runner for Fitocracy research', ['New fito_run.py runs every collection step in order, uploads new finds every 10 minutes and shows live status here.', 'Admin Fitocracy tab now shows a ready command with your token filled in.'], 'new'],
    ['3.19.5', '2026-11-23 11:39', 'Fitocracy archive: real levels, live status, add-data forms', ['Levels tab now leads with real Fitocracy level data, with our curve as comparison.', 'Live collection status, OCR results and downloads on the archive page.', 'Visitors can add level and points data they can see on a Fitocracy page.'], 'improve'],
    ['3.19.4', '2026-11-23 10:56', 'Fitocracy archive page redesigned', ['New tabs: overview, calibration (real Fitocracy points vs ours), levels, a points calculator, and the sources grouped by usefulness.', 'Confidence ratings for each kind of data.'], 'improve'],
    ['3.19.3', '2026-11-22 14:27', 'Update log', ['This page: every update and fix with its date and how long ago it was.'], 'new'],
    ['3.19.2', '2026-11-22 14:27', 'API guide page fixed', ['The API guide (linked from Connect) showed an error. It works again.'], 'fix'],
    ['3.19.1', '2026-11-22 12:16', 'Smaller privacy notice', ['The visitor-statistics notice is now one slim line with Accept / Decline and never reappears after you choose.'], 'improve'],
    ['3.19', '2026-11-22 11:51', 'Privacy-friendly visitor statistics', ['Anonymous visit counting (no IP stored) plus an optional Accept to recognise returning visitors.', 'Respects Do Not Track and Global Privacy Control.', 'New admin Stats tab; privacy page updated.'], 'new'],
    ['3.18b', '2026-11-22 10:39', 'Admin: delete test accounts', ['Admins can delete a user (and all their data) from the users list.'], 'new'],
    ['3.18', '2026-11-22 10:36', 'Warm-up sets now count', ['Warm-up sets earn half points. Weight units are tidier for lb users.'], 'improve'],
    ['3.17b', '2026-11-22 10:26', 'Welcome setup after registering', ['New members get a quick setup: weight, gender and goal. Gym is optional.'], 'new'],
    ['3.17', '2026-11-22 10:20', 'Stay signed in + separate widgets', ['You stay signed in for 90 days on your device.', 'MyFitLevel and SnakeDiet widgets are separate, with previews and a Lively Wallpaper guide.'], 'new'],
    ['3.16c', '2026-11-22 10:13', 'My lists fixed', ['The lists page no longer errors.'], 'fix'],
